// src/models/user.model.ts
export interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  role: 'admin' | 'editor' | 'viewer';
}

// src/dto/user.dto.ts
export class UserDto {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  role: string;
  fullName: string;
}

// src/mappers/user.mapper.ts
export class UserMapper {
  toDto(user: User): UserDto {
    return {
      id: user.id,
      email: user.email,
      firstName: user.firstName,
      lastName: user.lastName,
      role: user.role,
      fullName: `${user.firstName} ${user.lastName}`,
    };
  }
  fromDto(dto: UserDto): User {
    return {
      id: dto.id,
      email: dto.email,
      firstName: dto.firstName,
      lastName: dto.lastName,
      role: dto.role as User['role'],
    };
  }
}

// src/validators/user.validator.ts
export class UserValidator {
  validate(user: Partial<User>): string[] {
    const errors: string[] = [];
    if (!user.email || !user.email.includes('@')) errors.push('Invalid email');
    if (!user.firstName || user.firstName.trim() === '') errors.push('First name required');
    if (!user.lastName || user.lastName.trim() === '') errors.push('Last name required');
    if (!user.role || !['admin', 'editor', 'viewer'].includes(user.role)) errors.push('Invalid role');
    return errors;
  }
}

// src/repositories/user.repository.ts
export class UserRepository {
  async findById(id: string): Promise<User | null> {
    const row = await this.db.query('SELECT id, email, first_name, last_name, role FROM users WHERE id = $1', [id]);
    if (!row[0]) return null;
    return { id: row[0].id, email: row[0].email, firstName: row[0].first_name, lastName: row[0].last_name, role: row[0].role };
  }
  async save(user: User): Promise<void> {
    await this.db.query('INSERT INTO users (id, email, first_name, last_name, role) VALUES ($1,$2,$3,$4,$5)',
      [user.id, user.email, user.firstName, user.lastName, user.role]);
  }
}
