export class PushNotification {
  constructor(public readonly deviceToken: string, public readonly title: string, public readonly body: string) {}
  getType() { return 'push'; }
}

// src/handlers/email.handler.ts
export class EmailHandler {
  async handle(notification: EmailNotification): Promise<void> {
    await this.emailClient.send(notification.to, notification.subject, notification.body);
  }
}

// src/handlers/sms.handler.ts
export class SmsHandler {
  async handle(notification: SmsNotification): Promise<void> {
    await this.smsClient.send(notification.to, notification.message);
  }
}

// src/handlers/push.handler.ts
export class PushHandler {
  async handle(notification: PushNotification): Promise<void> {
    await this.pushClient.send(notification.deviceToken, notification.title, notification.body);
  }
}

// src/dispatcher.ts
export class NotificationDispatcher {
  async dispatch(notification: EmailNotification | SmsNotification | PushNotification): Promise<void> {
    if (notification.getType() === 'email') {
      await new EmailHandler().handle(notification as EmailNotification);
    } else if (notification.getType() === 'sms') {
      await new SmsHandler().handle(notification as SmsNotification);
    } else if (notification.getType() === 'push') {
      await new PushHandler().handle(notification as PushNotification);
    }
  }
}
